create table if not exists public.crm_experiment_promotions(id uuid primary key default gen_random_uuid(),experiment_id uuid not null references public.crm_experiments(id) on delete cascade,variant_id uuid not null references public.crm_experiment_variants(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,approved_by uuid not null references auth.users(id) on delete restrict,status text not null default 'approved',approved_at timestamptz not null default now(),metadata jsonb not null default '{}'::jsonb);
create index if not exists crm_experiment_promotions_owner_idx on public.crm_experiment_promotions(user_id,experiment_id,approved_at desc);
alter table public.crm_experiment_promotions enable row level security;
drop policy if exists crm_experiment_promotions_owner on public.crm_experiment_promotions;
create policy crm_experiment_promotions_owner on public.crm_experiment_promotions for select using(user_id=auth.uid());
create or replace function public.crm_experiment_promote_winner(p_experiment_id uuid,p_variant_id uuid,p_reason text default null) returns jsonb language plpgsql security invoker set search_path=public as $$ declare e public.crm_experiments%rowtype; v public.crm_experiment_variants%rowtype; report jsonb; eligible boolean; begin select * into e from public.crm_experiments where id=p_experiment_id and user_id=auth.uid() for update; if not found then raise exception 'experiment_not_found'; end if; select * into v from public.crm_experiment_variants where id=p_variant_id and experiment_id=p_experiment_id; if not found then raise exception 'variant_not_found'; end if; report:=public.crm_experiment_report(p_experiment_id); eligible:=coalesce((report->'guardrails'->>'winner_eligible')::boolean,false) and exists(select 1 from jsonb_array_elements(coalesce(report->'variants','[]'::jsonb)) x where (x->>'variant_id')::uuid=p_variant_id and coalesce((x->>'eligible_for_winner')::boolean,false)); if not eligible then raise exception 'winner_not_eligible'; end if; update public.crm_experiments set status='completed',updated_at=now() where id=p_experiment_id; insert into public.crm_experiment_promotions(experiment_id,variant_id,user_id,approved_by,status,metadata) values(p_experiment_id,p_variant_id,auth.uid(),auth.uid(),'approved',jsonb_build_object('reason',p_reason,'report',report)); return jsonb_build_object('ok',true,'experiment_id',p_experiment_id,'variant_id',p_variant_id,'status','approved','report',report,'approved_at',now()); end; $$;
revoke all on function public.crm_experiment_promote_winner(uuid,uuid,text) from public,anon;
grant execute on function public.crm_experiment_promote_winner(uuid,uuid,text) to authenticated;
create or replace function public.crm_experiment_guardrail_status(p_experiment_id uuid) returns jsonb language sql stable set search_path=public as $$ with e as(select id from public.crm_experiments where id=p_experiment_id and user_id=auth.uid()),v as(select v.id,v.name from public.crm_experiment_variants v join e on e.id=v.experiment_id),stats as(select v.id,v.name,count(distinct x.subject_key)::int exposures,count(distinct case when o.outcome in('converted','conversion','recovered','recovery') then o.subject_key end)::int positive from v left join public.crm_experiment_exposures x on x.variant_id=v.id left join public.crm_experiment_outcomes o on o.variant_id=v.id and o.experiment_id=p_experiment_id group by v.id,v.name),g as(select coalesce(max(min_sample_size),100)::int min_sample,coalesce(max(max_regression),0)::numeric max_regression from public.crm_experiment_guardrails where experiment_id=p_experiment_id and enabled),base as(select coalesce((select positive::numeric/nullif(exposures,0) from stats order by name limit 1),0) baseline_rate),elig as(select s.* from stats s cross join g cross join base where s.exposures>=g.min_sample and (g.max_regression<=0 or s.positive::numeric/nullif(s.exposures,0)>=base.baseline_rate*(1-g.max_regression))) select jsonb_build_object('experiment_id',p_experiment_id,'variant_stats',coalesce((select jsonb_agg(to_jsonb(s) order by s.name) from stats s),'[]'::jsonb),'guardrails',jsonb_build_object('minimum_sample_size',(select min_sample from g),'max_regression',(select max_regression from g)),'winner_eligible',exists(select 1 from elig),'eligible_variant_ids',coalesce((select jsonb_agg(id order by name) from elig),'[]'::jsonb),'generated_at',now()) $$;
revoke all on function public.crm_experiment_guardrail_status(uuid) from public,anon;
grant execute on function public.crm_experiment_guardrail_status(uuid) to authenticated;
